@Test
public void constructorValidationThrowsExceptionOnNulls_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> new DocumentType("html", null, null));
}

@Test
public void testThrowsOnAddNullText_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { Document doc = Jsoup.parse("<div id=1><p>Hello</p></div>"); Element div = doc.getElementById("1"); div.appendText(null); });
}

@Test
public void testThrowsOnPrependNullText_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { Document doc = Jsoup.parse("<div id=1><p>Hello</p></div>"); Element div = doc.getElementById("1"); div.prependText(null); });
}

@Test public void validatesKeysNotEmptyViaSet_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { Attribute attr = new Attribute("One", "Check"); attr.setKey(" "); });
    }

@Test
public void bodyAfterParseThrowsValidationError_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { Connection.Response res = Jsoup.connect(echoUrl).execute(); Document doc = res.parse(); String body = res.body(); });
}

@Test public void canCreateEmptyConnection_2_oe() {
    HttpConnection con = new HttpConnection();
    // removed other assertion
    assertThrows(IllegalArgumentException.class, () -> { URL url = con.request().url(); });
    }

@Test public void throwsOnOddData_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { Connection con = HttpConnection.connect("http://example.com/"); con.data("Name", "val", "what"); });
    }
